public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null) {
        return result;
    }
    int n = nums.length;
    if (n == 0) {
        result.add(new ArrayList<>());
        return result;
    }
    boolean[] used = new boolean[n];
    List<Integer> current = new ArrayList<>(n);
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, used, current, result);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Validate strings and find minimum length
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            throw new IllegalArgumentException("String list contains null element");
        }
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) {
        return 0;
    }

    int low = 1;
    int high = minLen;
    int best = 0;

    while (low <= high) {
        int mid = (low + high) >>> 1;
        if (existsCandidate(mid, strings)) {
            best = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return best;
}

private boolean existsCandidate(int length, List<String> strings) {
    String first = strings.get(0);
    int limit = first.length() - length;
    for (int i = 0; i <= limit; i++) {
        String candidate = first.substring(i, i + length);
        String rev = new StringBuilder(candidate).reverse().toString();
        boolean ok = true;
        for (String s : strings) {
            if (!(s.contains(candidate) || s.contains(rev))) {
                ok = false;
                break;
            }
        }
        if (ok) {
            return true;
        }
    }
    return false;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null) {
        throw new IllegalArgumentException("Grid cannot be null");
    }
    int rows = grid.length;
    if (rows == 0) {
        return 0;
    }
    int cols = -1;
    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) {
            throw new IllegalArgumentException("Row " + r + " is null");
        }
        if (cols == -1) {
            cols = grid[r].length;
            if (cols == 0) {
                return 0;
            }
        } else if (grid[r].length != cols) {
            throw new IllegalArgumentException("Row " + r + " length differs from others");
        }
        for (int c = 0; c < cols; c++) {
            char ch = grid[r][c];
            if (ch != '*' && ch != '@') {
                throw new IllegalArgumentException("Invalid character '" + ch + "' at (" + r + "," + c + ")");
            }
        }
    }

    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    java.util.function.BiConsumer<Integer, Integer> dfs = new java.util.function.BiConsumer<Integer, Integer>() {
        @Override
        public void accept(Integer r, Integer c) {
            visited[r][c] = true;
            for (int i = 0; i < 8; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    !visited[nr][nc] && grid[nr][nc] == '@') {
                    accept(nr, nc);
                }
            }
        }
    };

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                dfs.accept(r, c);
            }
        }
    }
    return deposits;
}

