}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (start == null || end == null) {
        throw new IllegalArgumentException("start and end cannot be null");
    }
    if (start.length != 1 || end.length != 1) {
        throw new IllegalArgumentException("start and end must be arrays of length 1");
    }
    int startNode = start[0];
    int endNode = end[0];
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        throw new IllegalArgumentException("start or end node out of bounds");
    }
    if (startNode == endNode) {
        return "can be travelled";
    }

    // Build adjacency list
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    if (paths != null) {
        for (int[] edge : paths) {
            if (edge == null || edge.length != 2) {
                continue; // skip invalid edges
            }
            int u = edge[0];
            int v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                continue; // skip out-of-bounds edges
            }
            adj[u].add(v);
            adj[v].add(u);
        }
    }

    // BFS to find path
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        for (int neighbor : adj[current]) {
            if (!visited[neighbor]) {
                if (neighbor == endNode) {
                    return "can be travelled";
                }
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date cannot be null");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Input must be in format 'MM dd yyyy'");
    }
    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid numeric values in date");
    }
    java.time.LocalDate localDate;
    try {
        localDate = java.time.LocalDate.of(year, month, day);
    } catch (java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date");
    }
    String monthName = localDate.getMonth()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    String weekday = localDate.getDayOfWeek()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    return monthName + " " + day + ", " + year + " is a " + weekday;
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        throw new IllegalArgumentException("Input array must contain at least two elements");
    }
    java.util.HashMap<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[]{map.get(complement), i};
        }
        map.put(nums[i], i);
    }
    throw new IllegalArgumentException("No two sum solution found");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    try {
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                return mid;
            }
            // Determine which side is sorted
            if (nums[left] <= nums[mid]) { // left side is sorted
                if (target >= nums[left] && target < nums[mid]) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            } else { // right side is sorted
                if (target > nums[mid] && target <= nums[right]) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected error, return -1
        return -1;
    }
    return -1;
}

