public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Divisor k must be positive");
    }
    if (arr.length % 2 != 0) {
        return false; // cannot pair all elements if count is odd
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        freq[r]++;
    }

    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled when k is even
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        throw new IllegalArgumentException("Number of nodes must be positive");
    }
    if (edges == null || edges.length != n - 1) {
        throw new IllegalArgumentException("Edges array must contain exactly n-1 edges");
    }
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple array length must be equal to n");
    }
    @SuppressWarnings("unchecked")
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) {
            throw new IllegalArgumentException("Each edge must contain exactly two nodes");
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge node indices out of bounds");
        }
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] time = new int[1];
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] time) {
    boolean has = hasApple[node];
    for (int neighbor : graph[node]) {
        if (neighbor == parent) {
            continue;
        }
        boolean childHas = dfs(neighbor, node, graph, hasApple, time);
        if (childHas) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (s.isEmpty()) {
        return "";
    }

    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.put(c, map.getOrDefault(c, 0) + 1);
    }

    StringBuilder result = new StringBuilder();

    while (!map.isEmpty()) {
        // Increasing phase
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        char last = entry.getKey();
        result.append(last);
        if (entry.getValue() == 1) {
            map.remove(last);
        } else {
            map.put(last, entry.getValue() - 1);
        }

        while (true) {
            java.util.Map.Entry<Character, Integer> nextEntry = map.higherEntry(last);
            if (nextEntry == null) {
                break;
            }
            char next = nextEntry.getKey();
            result.append(next);
            if (nextEntry.getValue() == 1) {
                map.remove(next);
            } else {
                map.put(next, nextEntry.getValue() - 1);
            }
            last = next;
        }

        // Decreasing phase
        if (map.isEmpty()) {
            break;
        }
        java.util.Map.Entry<Character, Integer> lastEntry = map.lastEntry();
        char lastChar = lastEntry.getKey();
        result.append(lastChar);
        if (lastEntry.getValue() == 1) {
            map.remove(lastChar);
        } else {
            map.put(lastChar, lastEntry.getValue() - 1);
        }
        last = lastChar;

        while (true) {
            java.util.Map.Entry<Character, Integer> prevEntry = map.lowerEntry(last);
            if (prevEntry == null) {
                break;
            }
            char prev = prevEntry.getKey();
            result.append(prev);
            if (prevEntry.getValue() == 1) {
                map.remove(prev);
            } else {
                map.put(prev, prevEntry.getValue() - 1);
            }
            last = prev;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    java.util.Set<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using updated values in same iteration
        for (int size = n - 1; size >= 0; size--) {
            if (dp[size].isEmpty()) continue;
            for (int sum : dp[size]) {
                dp[size + 1].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    // We only need the last two values
    int prevPrev = 0; // dp[0]
    int prev = 0;     // dp[1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev = prev + cost[i - 1];
        int costFromPrevPrev = prevPrev + cost[i - 2];
        int current = Math.min(costFromPrev, costFromPrevPrev);
        prevPrev = prev;
        prev = current;
    }
    return prev; // dp[n]
}

