public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string s cannot be null");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }
    int n = s.length();
    int totalCodes = 1 << k;
    if (n < totalCodes) {
        return false;
    }
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;
    int curr = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            throw new IllegalArgumentException("String s must be binary");
        }
        curr = ((curr << 1) & mask) | (c - '0');
        if (i >= k - 1) {
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == totalCodes) {
                    return true;
                }
            }
        }
    }
    return false;
}

