    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = sb.length();
        if (len > 0) {
            char last = sb.charAt(len - 1);
            if (Math.abs(c - last) == 32) { // opposite case same letter
                sb.deleteCharAt(len - 1);
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    return dfs(0, new java.util.HashSet<>(), s);
}

private int dfs(int index, java.util.Set<String> used, String s) {
    if (index == s.length()) {
        return 0;
    }
    int max = 0;
    for (int i = index; i < s.length(); i++) {
        String sub = s.substring(index, i + 1);
        if (!used.contains(sub)) {
            used.add(sub);
            int current = 1 + dfs(i + 1, used, s);
            if (current > max) {
                max = current;
            }
            used.remove(sub);
        }
    }
    return max;
}

public int minOperations(String[] logs) {
    if (logs == null) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else if (log.equals("./")) {
            // stay in current folder, do nothing
        } else {
            // assume it's a folder name ending with '/'
            depth++;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive");
    }
    int minSum = n;          // all 'a'
    int maxSum = 26 * n;     // all 'z'
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k must be between " + minSum + " and " + maxSum);
    }

    char[] result = new char[n];
    // start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - minSum; // how much we need to add
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max we can add to this position
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

