}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        throw new IllegalArgumentException("Matrix must not be null or empty");
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        throw new IllegalArgumentException("Matrix rows must not be empty");
    }
    // Validate that all rows have the same length
    for (int i = 1; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must have the same length");
        }
    }

    int[][] horizontal = new int[m][n];
    int[][] vertical   = new int[m][n];
    int[][] diagonal   = new int[m][n];
    int[][] antiDiag   = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                vertical[i][j]   = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                diagonal[i][j]   = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                antiDiag[i][j]   = (i > 0 && j < n - 1 ? antiDiag[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horizontal[i][j], vertical[i][j]),
                                        Math.max(diagonal[i][j], antiDiag[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j]   = 0;
                diagonal[i][j]   = 0;
                antiDiag[i][j]   = 0;
            }
        }
    }
    return maxLen;
}

