public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int n = A.length;
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    int[] count = new int[1];
    int maxVal = A[n - 1];
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    backtrack(0, -1, A, used, isSquare, count);
    return count[0];
}

private static void backtrack(int depth, int lastIndex, int[] A, boolean[] used, boolean[] isSquare, int[] count) {
    int n = A.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
        if (lastIndex != -1 && !isSquare[A[lastIndex] + A[i]]) continue;
        used[i] = true;
        backtrack(depth + 1, i, A, used, isSquare, count);
        used[i] = false;
    }
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = heights.length;
    if (n == 0) {
        return 0;
    }
    for (int h : heights) {
        if (h < 0) {
            throw new IllegalArgumentException("Heights must be non-negative");
        }
    }

    int[] stack = new int[n + 1]; // stack of indices
    int top = -1;
    long maxArea = 0;

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }

    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null) {
        throw new IllegalArgumentException("Input matrix cannot be null");
    }
    int m = mat.length;
    if (m == 0) {
        return new int[0];
    }
    int n = mat[0].length;
    if (n == 0) {
        return new int[0];
    }
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    for (int s = 0; s <= m + n - 2; s++) {
        int rowStart = Math.min(s, m - 1);
        int rowEnd = Math.max(0, s - n + 1);
        if (s % 2 == 0) {
            for (int row = rowStart; row >= rowEnd; row--) {
                int col = s - row;
                result[idx++] = mat[row][col];
            }
        } else {
            for (int row = rowEnd; row <= rowStart; row++) {
                int col = s - row;
                result[idx++] = mat[row][col];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    try {
        char[] digits = Integer.toString(n).toCharArray();
        int i = digits.length - 2;
        while (i >= 0 && digits[i] >= digits[i + 1]) {
            i--;
        }
        if (i < 0) {
            return -1; // no larger permutation
        }
        int j = digits.length - 1;
        while (digits[j] <= digits[i]) {
            j--;
        }
        char tmp = digits[i];
        digits[i] = digits[j];
        digits[j] = tmp;
        int left = i + 1, right = digits.length - 1;
        while (left < right) {
            tmp = digits[left];
            digits[left] = digits[right];
            digits[right] = tmp;
            left++;
            right--;
        }
        long result = Long.parseLong(new String(digits));
        return result > Integer.MAX_VALUE ? -1 : (int) result;
    } catch (Exception e) {
        return -1;
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        throw new IllegalArgumentException("points must contain exactly 3 points");
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            throw new IllegalArgumentException("each point must be an array of two integers");
        }
    }
    long x1 = points[0][0], y1 = points[0][1];
    long x2 = points[1][0], y2 = points[1][1];
    long x3 = points[2][0], y3 = points[2][1];
    long area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;
    for (int i = 1; i < n; i++) {
        long nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = (int) nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = (long) ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = (long) ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = (long) ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int maxLen = 0;
    int currentLen = 0;
    char prev = '\0';
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (i == 0 || c != prev) {
            currentLen = 1;
        } else {
            currentLen++;
        }
        if (currentLen > maxLen) {
            maxLen = currentLen;
        }
        prev = c;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be at least 1");
    }
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        if (i > n) {
            break;
        }
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    result.add(current);
    for (int digit = 0; digit <= 9; digit++) {
        long next = (long) current * 10 + digit;
        if (next > n) {
            break;
        }
        dfs((int) next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    if (nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    long sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return (int) sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        int sqrt = (int) Math.sqrt(i);
        for (int j = 1; j <= sqrt; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            result.append(' ');
            word.setLength(0);
        } else {
            word.append(c);
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());
    return result.toString();
}
